const GRN = '#22c55e';
const RED = '#ef4444';

// Decision-card zone texts. `supLine` is the page's own support line (11 Feb → 28 Jul) valued today.
// The zone chain in page.jsx: ≥0.85 target · >0.7365 extended · ≥TA.invalidation.level breakout · >0.3281 failed · else broken.
export function zones(supLine) {
  return {
    target: ['EN LA MEDIDA DE LA BANDERA — zona de tomar parcial', GRN, 'Sobre 0.85. La medida al 61.8% del impulso está acá. Sin revenue pagado publicado, este es el lugar de vender otra parte, no de sumar.'],
    extended: ['NUEVOS MÁXIMOS — bandera resuelta arriba', GRN, 'Sobre 0.7365 (máximo del 5 Oct). El path alcista está intacto y acelerando; no es zona de entrar: el próximo nivel para sumar es el retest de 0.68–0.74 que aguante.'],
    breakout: ['SOBRE 0.3758 — el techo de la banda recuperado, sesgo bajista anulado', GRN, 'Entre 0.3758 y 0.7365. El cierre bajo 0.3281 (21 Nov) y el cierre bajo la EMA200 quedaron como barridos: el techo del rebote del 16–19 Nov se recuperó al cierre y el camino es 0.3878–0.3947 (el escalón perdido y el máximo de junio), la EMA100 (0.3949), 0.402 (la invalidación del motor), el racimo (0.3728–0.4073), 0.4466, 0.4657 (la invalidación vieja), 0.49 y 0.5607 (el piso de la bandera — recuperado, la bandera se reconstruye). Sumar solo con 2× volumen ($1.0M, verdes) y NOS subiendo más que SOL; sin eso, es un rebote largo dentro de la devolución.'],
    failed: ['ENTRE 0.3281 Y 0.3758 — de vuelta sobre el mínimo del pullback; sesgo bajista por la regla hasta 0.3758: la banda 0.3281–0.3758 es la que hay que reconstruir, con la barra verde que la devolución nunca trajo', RED, `Bajo 0.3758 y sobre 0.3281. La devolución completó la secuencia entera: 0.49 cerrado dos veces (19 y 24 Oct), el 61.8% (0.4466) resuelto abajo, la EMA100 y el máximo de junio (0.3947) cerrados en una vela (31 Oct), 0.3878 (4 Nov), un rebote de +20.1% (5 Nov, 0.4657) devuelto en seis velas, la EMA100 cerrada el 11 Nov (0.4031 — el stop del 5 Nov), 0.3878 cerrado el 13 Nov (0.3758 — el stop de lo legacy), el 78.6% (0.3679) y la EMA200 cerrados el 15 Nov (0.3281), cuatro cierres verdes que recuperaron la medida sin la barra (0.3723, 19 Nov), devueltos en dos velas propias: 0.3679 cerrado de vuelta el 20 Nov (0.3582) y la EMA200 y 0.3281 cerrados el 21 Nov (0.32, −10.7% con SOL −5.9%) con la barra más grande de 30 días ($1.11M), roja; el 22 Nov 0.3175 (−0.8% con SOL +2.1%) — el cierre más bajo desde el breakout, 0.3125 aguantado por 1.6%. Si el precio está acá, volvió sobre el mínimo del pullback desde abajo: no hay posición con stop en esta página (el 5 Nov salió en 0.4031, lo legacy en 0.3758, la novena entrada no imprimió). Lo que vale es cómo volvió — recuperado al cierre con vela de rechazo, $1.3M+ verdes y NOS sobre SOL, el 21–22 Nov fue el barrido del mínimo y la décima entrada está impresa por arriba (stop en el cierre bajo el rail); recuperado con $0.4M, es el quinto rebote llegando al nivel perdido y se vende — el cuarto recuperó la medida sin la barra y se devolvió entero. Arriba quedan la EMA200 (0.3559), 0.3582, 0.3679 (la medida), 0.3723 y 0.3758 — la invalidación, movida desde 0.4657 el 21 Nov: hasta ahí 0.3281–0.3559 es donde se reduce lo que no se quiere tener debajo del rail. Abajo, 0.3125 (el breakout del 21 Sep, aguantado al cierre el 22 Nov), el rail del año en ~${supLine.toFixed(3)}–0.2955 y 0.2675 (el origen). El sesgo bajista lo anula solo un cierre sobre 0.3758 con 2× volumen y NOS sobre SOL.`],
    broken: ['BAJO 0.3281 — el mínimo del pullback cerrado el 21 Nov (0.32) con la barra más grande de 30 días, roja, y el 22 Nov más abajo (0.3175) con el benchmark verde; 0.3125 aguantado al cierre por 1.6%, el rail del año (~0.2955) a 8%: entre el mínimo perdido y el rail, sin barra', RED, 'Bajo 0.3281. El impulso 0.2675 → 0.7365 devolvió el 93%: el 61.8% (25–29 Oct), la EMA100 y 0.3947 (31 Oct), 0.3878 (4 Nov y de vuelta el 13 Nov — el stop de lo legacy, con la primera barra sobre el promedio, roja), el 78.6% (0.3679) y la EMA200 (15 Nov, 0.3281), el 21 Nov el mínimo del pullback — el retest que decidía si el 15 Nov fue el piso — cerrado por 2.5% (0.32, −10.7% con SOL −5.9%) con $1.11M (registrada al cierre; $1.25M en vivo el sábado), el 212% del promedio y la barra más grande de 30 días: la segunda vez que la barra llega roja; y el 22 Nov 0.3175 (−0.8% con SOL +2.1%) — el cierre más bajo desde el breakout, sin barra. Lo que quedaba salió en 0.3758: si el precio está acá, no hay posición con stop que siga adentro, y la novena entrada (0.3758 con la barra, o 0.3281 aguantado con la barra) no imprimió — la barra llegó, del otro lado. El sábado 0.2999 en vivo cerró 0.3125 en vivo y alcanzó el rail por la regla; el cierre del 22 Nov devolvió las dos cosas: 0.3125 aguantado por 1.6%, el rail no alcanzado (a 7%). Hoy 0.3216, +1.3% con SOL −0.1%, con el 75% del promedio: 0.32 recuperado por empate, 0.3281 a 2%, el rail a 8%. La décima entrada sigue siendo la misma por los dos lados y no imprimió ninguno: el rail aguantado al cierre con vela de rechazo abajo y $1.3M+ verdes (25%, stop en el cierre bajo 0.2675) — el rail todavía no llegó al cierre —, o el cierre de vuelta sobre 0.3281 con la misma barra y NOS sobre SOL (25%, stop en el cierre bajo el rail) — el precio está a 2% y la barra es el 75%. Si el rail se cierra con la barra, 0.2675 llega en días y debajo del rail esta página no tiene un número que llamar piso — ahí la tesis se mira por la red (compute hours, revenue pagado), no por el chart. No se compra 0.32 porque el rail "aguantó": el rail no se probó al cierre, 0.3125 aguantó por 1.6% y el rebote es del 1% con $0.37M — se compra el cierre que aguante el rail o recupere 0.3281 con la barra verde que la devolución entera nunca trajo.'],
  };
}

// "Si ya tenés NOS" — the three TA bullets (the staking bullet stays in page.jsx).
export function HoldBullets({ B, supLine }) {
  return (<>
    <B c={RED}>El cierre bajo <b>0.49</b> se imprimió dos veces — 0.4826 (19 Oct) y 0.4657 (24 Oct): el stop mental del plan se cumplió, el sesgo es bajista por la regla y desde ahí el precio completó la secuencia bajista entera — el 61.8% (0.4466), 0.4304, la EMA100 y el máximo de junio (0.3947) en una vela, 0.3897, 0.3878 (4 Nov). <b>El 5 Nov cerró 0.4657, +20.1% con SOL +2.9%</b> con una barra de $1.23M como máximo (la condición de $1.3M no se cumplió); seis velas lo devolvieron; <b>el 11 Nov cerró la EMA100 (0.4031): el stop de la entrada del 5 Nov imprimió</b>; <b>el 13 Nov cerró 0.3878 (0.3758, −5.4% con SOL −1.9%): el stop de lo que se tenía de antes imprimió</b> — lo que quedaba salió en 0.3758. El 15 Nov el 78.6% (0.3679) y la EMA200 se cerraron en una vela (0.3281); cuatro cierres verdes recuperaron la medida sin la barra (0.3723, 19 Nov); <b>el 20 Nov la cerraron de vuelta (0.3582, −3.8% con SOL −0.7% — propia) y el 21 Nov cerró 0.32 (−10.7% con SOL −5.9%): la EMA200 y 0.3281 — el mínimo del pullback, el retest que decidía — cerrados con $1.11M (registrada al cierre), el 212% del promedio, la barra más grande de 30 días, roja</b>; el 22 Nov cerró 0.3175 (−0.8% con SOL +2.1%) — el cierre más bajo desde el breakout, 0.3125 aguantado por 1.6%, sin barra. Hoy 0.3216, +1.3% con SOL −0.1%, con el 75% del promedio: 0.32 recuperado por empate, 0.3281 a 2%, el rail a 8%. No se repone en 0.32 porque el rail no se probó al cierre y la barra no está: se repone con el cierre que aguante el rail con vela de rechazo abajo y <b>$1.3M+ verdes</b>, o con el cierre de vuelta sobre 0.3281 con la misma barra y NOS sobre SOL.</B>
    <B c={RED}><b>No se suma en 0.32 porque el precio está entre el mínimo perdido (0.3281, a 2%) y el rail (~0.2955, a 8%) con el 75% del promedio, un día después de que la barra más grande del mes llegara del lado del vendedor.</b> La invalidación bajó de 0.4657 a <b>0.3758</b> (el techo de la banda, el techo del rebote de cuatro verdes del 16–19 Nov — el criterio de la casa; el motor subió la suya a 0.402 y esta página se queda en el techo del rebote) con 2× volumen ($1.0M) y NOS sobre SOL — 17% arriba —: hasta ahí cada rebote es para reducir lo que no querés tener debajo del rail, y la zona es <b>0.3281–0.3559</b> (el mínimo perdido y la EMA200) si llega sin la barra verde. Lo que cambió esta semana es que la barra llegó — y llegó roja: cinco semanas de devolución con el 50–100% del promedio, dos barras sobre el promedio en total (13 Nov $0.61M, 21 Nov $1.11M), las dos rojas, las dos cerrando un escalón; y el día siguiente, el 22 Nov, la vela más chica de la semana con el benchmark verde y sin tamaño. El RSI cruzó 30 por primera vez en la devolución el sábado (19.5) y volvió a 25.6 con el rebote — segunda revisión debajo —, el histograma del MACD frena por primera vez desde que cruzó (−0.0031 desde −0.0045), la EMA20 está 8.5% bajo la EMA50 — el cruce del 4 Nov abriéndose un poco más —, el motor sigue en 2/7 y mide el rail a un mes — el mismo +1M que esta página. Se suma con el cierre que aguante el rail con vela y $1.3M+ verdes, o con el cierre de vuelta sobre 0.3281 con la misma barra; no en 0.32 porque el rebote es del 1% y la barra es del vendedor o de nadie.</B>
    <B c={RED}>Si no tenés stop porque sos legacy: <b>0.3281</b> (el mínimo perdido), la EMA200 (<b>0.3559</b>), 0.3679 (la medida) y 0.3758 (la invalidación) están arriba (2%, 11%, 14% y 17%); el precio en vivo está 3% sobre 0.3125 (el breakout, aguantado al cierre el 22 Nov), 8% sobre el rail del motor (~0.2955) y 12% sobre la línea de esta página (~{supLine.toFixed(3)}). El siguiente nivel abajo es 0.3125, después el rail, después <b>0.2675</b> (el origen del impulso, la medida del motor a tres meses — a 17%) y después 0.2528 y 0.2431 (los toques de agosto y julio). Entre el rail y 0.2675 hay 9%; debajo del rail no hay un nivel que esta página llame piso. Si querés reducir, el lugar es 0.3281–0.3559 en un rebote sin la barra verde — y 0.3281 está a 2% con el 75% del promedio: si el rebote de hoy llega ahí sin tamaño, es ese lugar. Si el rail se cierra por abajo con la barra, lo que decide no es el chart: es si la red (compute hours sobre 150k, revenue pagado publicado) justifica tener un alt de $32M debajo de su rail de nueve meses.</B>
  </>);
}

// "Si querés entrar" — the three TA bullets (the sizing bullet stays in page.jsx).
export function EnterBullets({ B }) {
  return (<>
    <B c={GRN}>No compres el rebote del 1% entre el mínimo perdido y el rail: la novena entrada que esta página escribió el 18–19 Nov tenía dos lados — el cierre sobre 0.3758 con vela, $1.3M+ y NOS sobre SOL, o el retest de 0.3281 que aguantara con la misma barra — y lo que imprimió fue lo contrario de los dos: 0.3758 nunca se cerró (tocado en vivo el 19 Nov), 0.3679 se cerró de vuelta el 20 Nov (0.3582, propia), el 21 Nov 0.3281 se cerró por abajo (0.32, −10.7% con SOL −5.9%) con $1.11M — la barra que faltaba, roja —, y el 22 Nov cerró más abajo (0.3175, −0.8% con SOL +2.1%) sin barra. Después de +175% en tres semanas la bandera se rompió por abajo, la EMA20 cedió, el 0.49 se cerró dos veces, la EMA50, el 61.8%, 0.4304, la EMA100 y 0.3947 se perdieron, el 5 Nov recuperó siete escalones sin la barra y los devolvió, el 13 Nov cerró 0.3878 con la primera barra roja sobre el promedio, el 15 Nov cerró la medida y la EMA200 en una vela de mercado, cuatro velas verdes propias recuperaron la medida sin la barra, dos velas rojas propias devolvieron todo con la barra, y la tercera roja llegó con el benchmark verde y sin tamaño. La red está igual: comprás el sector, no el activo. NOS −0.8% con SOL +2.1% el 22 Nov, +1.3% con SOL −0.1% hoy: el movimiento es propio en las dos direcciones, y propio con $0.37M es nadie — ni el vendedor del viernes ni un comprador.</B>
    <B c={GRN}>Las entradas del plan (0.54–0.56, 0.49–0.502 y el retest de la EMA50 en 0.467) se cancelaron las tres. La cuarta (el retest de 0.3947) llegó con dos de tres. La quinta imprimió el 5 Nov con la barra corta y salió en su stop el 11 Nov (0.4031). La sexta (el retest de la EMA100) no imprimió. La séptima (el retest de 0.3878–0.3947) no imprimió: el nivel se cerró el 13 Nov. La octava (el 78.6% aguantado con la barra, o 0.3878 recuperado) no imprimió: la medida se cerró el 15 Nov. La novena (0.3758 recuperado con la barra, o 0.3281 aguantado con la barra) no imprimió: el techo de la banda no se cerró, el mínimo se cerró el 21 Nov con la barra roja. La décima es ésta, y sigue abierta por los dos lados: <b>el rail del año (~0.2955, a 8%) que aguante al cierre</b> con vela de rechazo abajo y <b>$1.3M+ verdes</b> — 25% del tamaño objetivo, stop en el cierre bajo <b>0.2675</b> — (el rail no llegó al cierre todavía: el sábado estuvo a 1.6% en vivo y el cierre volvió a 0.3175), o <b>el cierre de vuelta sobre 0.3281</b> (el mínimo perdido, a 2%) con la misma barra y NOS sobre SOL — 25%, stop en el cierre bajo el rail — (el precio está a 2% y la barra es el 75% del promedio: sin la barra, un cierre sobre 0.3281 es el quinto rebote llegando al nivel perdido, no la entrada); se compra con el cierre impreso con la barra verde, no con un rebote del 1% un domingo con $0.37M. Si el rail no aguanta, no hay siguiente entrada en el chart: 0.2675 (el origen) con $1.3M+ y vela que cierre arriba sería la primera debajo del rail, y esta página la escribe solo con la red justificándola. Arriba, el cierre sobre <b>0.3758</b> con 2× volumen ($1.0M) y NOS sobre SOL anula el sesgo y es la entrada por fuerza.</B>
    <B c={GRN}>Entrada por fuerza: cierre diario &gt; <b>0.3758</b> (el techo de la banda y del rebote del 16–19 Nov — la invalidación, movida desde 0.4657 el 21 Nov; el motor puso la suya en 0.402) con 2× volumen y NOS sobre SOL, después &gt; 0.3947, &gt; 0.4657 (la invalidación vieja) y &gt; 0.5607 (piso de la bandera). Entrás más caro, pero con el sesgo de vuelta alcista. Un cierre sobre 0.3281, la EMA200 (0.3559) o 0.3679 con el libro vacío no es entrada: es el rebote llegando al nivel perdido — el segundo (0.455, 8 Nov) duró una vela, el tercero no llegó al racimo, el cuarto (0.3381 → 0.3723, 16–19 Nov) recuperó la medida sin la barra y se devolvió entero en dos velas, y el quinto, si el rebote de hoy cierra, arranca con el 75% del promedio; con $1.3M+ verdes y NOS sobre SOL, el cierre sobre 0.3281 es la décima entrada por arriba y se acompaña con el stop en el cierre bajo el rail.</B>
  </>);
}

// "Pattern read" box (the left column under the structure chart).
